function Read-TaskStore {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        return @()
    }

    $content = Get-Content -LiteralPath $Path -Raw
    if ([string]::IsNullOrWhiteSpace($content)) {
        return @()
    }

    $parsed = ConvertFrom-Json -InputObject $content
    return @($parsed)
}

function Write-TaskStore {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Tasks
    )

    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    Write-AtomicJsonArray -Path $Path -Values $Tasks
}

function Get-TemplateStorePath {
    param([Parameter(Mandatory)][string]$DataFile)

    $parent = Split-Path -Parent $DataFile
    $fileName = [System.IO.Path]::GetFileNameWithoutExtension($DataFile)
    if ($parent) {
        return Join-Path $parent "$fileName.templates.json"
    }
    return "$fileName.templates.json"
}

function Read-TemplateStore {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        return @()
    }

    $content = Get-Content -LiteralPath $Path -Raw
    if ([string]::IsNullOrWhiteSpace($content)) {
        return @()
    }

    return @(ConvertFrom-Json -InputObject $content)
}

function Write-TemplateStore {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Templates
    )

    Write-AtomicJsonArray -Path $Path -Values $Templates
}

function Write-AtomicJsonArray {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Values
    )

    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    $temporary = "$Path.$([guid]::NewGuid().ToString('N')).tmp"
    try {
        $json = ConvertTo-Json -InputObject @($Values) -Depth 8
        [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
        [System.IO.File]::Move($temporary, $Path, $true)
    }
    finally {
        if (Test-Path -LiteralPath $temporary) {
            Remove-Item -LiteralPath $temporary -Force
        }
    }
}

function ConvertFrom-TaskForgeArguments {
    param([AllowEmptyCollection()][string[]]$Arguments)

    $options = [ordered]@{}
    for ($index = 0; $index -lt $Arguments.Count; $index++) {
        $token = $Arguments[$index]
        if (-not $token.StartsWith('--')) {
            throw "Unexpected argument: $token"
        }

        $name = $token.Substring(2)
        if ([string]::IsNullOrWhiteSpace($name)) {
            throw 'Option name cannot be empty.'
        }
        if ($options.Contains($name)) {
            throw "Duplicate option: --$name"
        }

        if (($index + 1) -lt $Arguments.Count -and -not $Arguments[$index + 1].StartsWith('--')) {
            $options[$name] = $Arguments[++$index]
        }
        else {
            $options[$name] = $true
        }
    }

    return $options
}

function Get-RequiredOption {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][string]$Name
    )

    if (-not $Options.Contains($Name) -or $Options[$Name] -is [bool] -or
        [string]::IsNullOrWhiteSpace([string]$Options[$Name])) {
        throw "Missing required option: --$Name"
    }
    return [string]$Options[$Name]
}

function Get-OptionValue {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][string]$Name
    )

    if (-not $Options.Contains($Name) -or $Options[$Name] -is [bool]) {
        throw "Missing required option: --$Name"
    }
    return [string]$Options[$Name]
}

function Get-ValidTemplateName {
    param([Parameter(Mandatory)][string]$Name)

    $trimmed = $Name.Trim()
    if ($trimmed.Length -gt 64 -or $trimmed -notmatch '^[A-Za-z0-9](?:[A-Za-z0-9 ._-]*[A-Za-z0-9])?$') {
        throw 'Template names must be 1-64 characters, start and end with a letter or number, and contain only letters, numbers, spaces, periods, underscores, or hyphens.'
    }
    return $trimmed
}

function Find-Template {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Templates,
        [Parameter(Mandatory)][string]$Name
    )

    return $Templates |
        Where-Object { [string]::Equals([string]$_.name, $Name, [System.StringComparison]::OrdinalIgnoreCase) } |
        Select-Object -First 1
}

function Write-TemplateBanner {
    $bannerPath = Join-Path (Split-Path -Parent $PSScriptRoot) 'assets/template.txt'
    Get-Content -LiteralPath $bannerPath
}

function Assert-KnownOptions {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Allowed
    )

    foreach ($name in $Options.Keys) {
        if ($name -notin $Allowed) {
            throw "Unknown option: --$name"
        }
    }
}

function Write-TaskForgeOutput {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()]$Value,
        [Parameter(Mandatory)][bool]$AsJson
    )

    if ($AsJson) {
        ConvertTo-Json -InputObject $Value -Depth 8 -Compress
    }
    else {
        [string]$Value
    }
}

Export-ModuleMember -Function *

[CmdletBinding()]
param(
    [Parameter(Position = 0)]
    [string]$Command = 'help',

    [Parameter(Position = 1, ValueFromRemainingArguments)]
    [string[]]$CliArguments = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

try {
    $commandName = $Command.ToLowerInvariant()
    $templateAction = $null
    $argumentsToParse = $CliArguments
    if ($commandName -eq 'template') {
        if ($CliArguments.Count -eq 0 -or $CliArguments[0].StartsWith('--')) {
            throw 'Missing template action: save, list, or remove.'
        }
        $templateAction = $CliArguments[0].ToLowerInvariant()
        $argumentsToParse = if ($CliArguments.Count -gt 1) { @($CliArguments[1..($CliArguments.Count - 1)]) } else { @() }
    }

    $options = ConvertFrom-TaskForgeArguments -Arguments $argumentsToParse
    $defaultDataFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/tasks.json'
    $dataFile = if ($options.Contains('data-file')) {
        Get-RequiredOption -Options $options -Name 'data-file'
    }
    else {
        $defaultDataFile
    }
    $asJson = $options.Contains('json')

    switch ($commandName) {
        'add' {
            Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'template', 'data-file', 'json')
            $template = $null
            if ($options.Contains('template')) {
                $templateName = Get-ValidTemplateName (Get-RequiredOption -Options $options -Name 'template')
                $templates = @(Read-TemplateStore -Path (Get-TemplateStorePath -DataFile $dataFile))
                $template = Find-Template -Templates $templates -Name $templateName
                if ($null -eq $template) {
                    throw "Template '$templateName' was not found."
                }
            }

            $title = if ($options.Contains('title')) {
                (Get-RequiredOption -Options $options -Name 'title').Trim()
            }
            elseif ($null -ne $template) {
                [string]$template.title
            }
            else {
                throw 'Missing required option: --title'
            }
            $description = if ($options.Contains('description')) {
                Get-OptionValue -Options $options -Name 'description'
            }
            elseif ($null -ne $template) {
                [string]$template.description
            }
            else {
                ''
            }

            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $task = [ordered]@{
                id = $nextId
                title = $title
                description = $description
                status = 'pending'
                createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            }
            Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
            if ($asJson) {
                Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
            }
            else {
                "Added task ${nextId}: $($task.title)"
            }
        }
        'list' {
            Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
            $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
            if ($asJson) {
                Write-TaskForgeOutput -Value $tasks -AsJson $true
            }
            elseif ($tasks.Count -eq 0) {
                'No tasks.'
            }
            else {
                $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
            }
        }
        'complete' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
            if ($null -eq $task) {
                throw "Task $id was not found."
            }
            $task.status = 'completed'
            Write-TaskStore -Path $dataFile -Tasks $tasks
            if ($asJson) {
                Write-TaskForgeOutput -Value $task -AsJson $true
            }
            else {
                "Completed task $id."
            }
        }
        'remove' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
            if ($remaining.Count -eq $tasks.Count) {
                throw "Task $id was not found."
            }
            Write-TaskStore -Path $dataFile -Tasks $remaining
            $summary = [pscustomobject]@{ removedId = $id }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                "Removed task $id."
            }
        }
        'template' {
            $templateStore = Get-TemplateStorePath -DataFile $dataFile
            switch ($templateAction) {
                'save' {
                    Assert-KnownOptions -Options $options -Allowed @('name', 'title', 'description', 'data-file', 'json')
                    $name = Get-ValidTemplateName (Get-RequiredOption -Options $options -Name 'name')
                    $title = (Get-RequiredOption -Options $options -Name 'title').Trim()
                    $description = if ($options.Contains('description')) {
                        Get-OptionValue -Options $options -Name 'description'
                    }
                    else {
                        ''
                    }
                    $templates = @(Read-TemplateStore -Path $templateStore)
                    if ($null -ne (Find-Template -Templates $templates -Name $name)) {
                        throw "Template '$name' already exists."
                    }
                    $template = [pscustomobject][ordered]@{
                        name = $name
                        title = $title
                        description = $description
                    }
                    Write-TemplateStore -Path $templateStore -Templates @($templates + $template)
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $template -AsJson $true
                    }
                    else {
                        Write-TemplateBanner
                        "Saved template '$name'."
                    }
                }
                'list' {
                    Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
                    $templates = @(Read-TemplateStore -Path $templateStore |
                        Sort-Object @{ Expression = { [string]$_.name }; Ascending = $true })
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $templates -AsJson $true
                    }
                    else {
                        Write-TemplateBanner
                        if ($templates.Count -eq 0) {
                            'No templates.'
                        }
                        else {
                            $templates | ForEach-Object {
                                if ([string]::IsNullOrEmpty([string]$_.description)) {
                                    "$($_.name): $($_.title)"
                                }
                                else {
                                    "$($_.name): $($_.title) - $($_.description)"
                                }
                            }
                        }
                    }
                }
                'remove' {
                    Assert-KnownOptions -Options $options -Allowed @('name', 'data-file', 'json')
                    $name = Get-ValidTemplateName (Get-RequiredOption -Options $options -Name 'name')
                    $templates = @(Read-TemplateStore -Path $templateStore)
                    $template = Find-Template -Templates $templates -Name $name
                    if ($null -eq $template) {
                        throw "Template '$name' was not found."
                    }
                    $remaining = @($templates | Where-Object {
                        -not [string]::Equals([string]$_.name, $name, [System.StringComparison]::OrdinalIgnoreCase)
                    })
                    Write-TemplateStore -Path $templateStore -Templates $remaining
                    $summary = [pscustomobject]@{ removedName = [string]$template.name }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $summary -AsJson $true
                    }
                    else {
                        Write-TemplateBanner
                        "Removed template '$($template.name)'."
                    }
                }
                default {
                    throw "Unknown template action: $templateAction"
                }
            }
        }
        'help' {
            Assert-KnownOptions -Options $options -Allowed @()
            @'
TaskForge
  add [--template NAME] [--title TEXT] [--description TEXT] [--data-file PATH] [--json]
  list [--data-file PATH] [--json]
  complete --id ID [--data-file PATH] [--json]
  remove --id ID [--data-file PATH] [--json]
  template save --name NAME --title TEXT [--description TEXT] [--data-file PATH] [--json]
  template list [--data-file PATH] [--json]
  template remove --name NAME [--data-file PATH] [--json]
'@
        }
        default {
            throw "Unknown command: $Command"
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}
